import * as React from "react"

type Severity = "critical" | "high" | "medium" | "low"

const severityClass: Record<Severity, string> = {
  critical: "text-[var(--severity-critical)] border-[var(--severity-critical)]",
  high: "text-[var(--severity-high)] border-[var(--severity-high)]",
  medium: "text-[var(--severity-medium)] border-[var(--severity-medium)]",
  low: "text-[var(--severity-low)] border-[var(--severity-low)]",
}

// severity values mirror contracts/finding.md; `blocks` arrives from the server on every
// finding (contracts/finding.md) — required here so display can never fail open
export function FindingBadge({
  severity,
  blocks,
  className = "",
}: {
  severity: Severity
  blocks: boolean
  className?: string
}) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 font-mono text-xs uppercase tracking-wide ${severityClass[severity]} ${className}`}
    >
      {blocks && (
        <>
          <span aria-hidden="true" className="size-1.5 rounded-full bg-current" />
          <span className="sr-only">blocking</span>
        </>
      )}
      {severity}
    </span>
  )
}
